[MemoryDiagnoser]
public class SnapshotComparison {
    public IEnumerable<string> Scenarios => SnapshotProbe.Keys();
    [ParamsSource(nameof(Scenarios))] public string Scenario { get; set; } = "";
    private SnapshotProbe _before = null!, _after = null!;
    [GlobalSetup] public void Setup() {
        if (OperatingSystem.IsWindows() || OperatingSystem.IsLinux()) Process.GetCurrentProcess().PriorityClass = ProcessPriorityClass.Normal;
        _before = SnapshotProbe.Load(Scenario, "baseline");
        _after = SnapshotProbe.Load(Scenario, "candidate");
        SnapshotProbe.ValidateEquivalent(_before, _after);
    }
    [Benchmark(Baseline = true)] public Task<object?> Before() => _before.Run();
    [Benchmark] public Task<object?> After() => _after.Run();
    [GlobalCleanup] public void Cleanup() { try { _before?.Dispose(); } finally { _after?.Dispose(); } }
}

public sealed class SnapshotProbe : IDisposable {
    private readonly object _instance;
    private readonly Func<Task<object?>> _run;
    private SnapshotProbe(object instance, Func<Task<object?>> run) { _instance = instance; _run = run; }
    public Task<object?> Run() => _run();
    public object? RunSynchronously() => _run().GetAwaiter().GetResult();
    public string? ExpectedResult { get; private set; }
    public string? OutputContract { get; private set; }
    public static void ValidateEquivalent(SnapshotProbe before, SnapshotProbe after) {
        string? oldValue = before.RunSynchronously()?.ToString();
        string? newValue = after.RunSynchronously()?.ToString();
        if (before.OutputContract is { } contract && after.OutputContract is { } otherContract) {
            if (contract != otherContract || oldValue != before.ExpectedResult || newValue != after.ExpectedResult)
                throw new InvalidDataException("Output differs from the independently validated CSV contract.");
        } else if (oldValue != newValue) {
            throw new InvalidDataException($"Baseline and candidate outputs differ: {oldValue} / {newValue}");
        }
    }
    private static Dictionary<string, JsonElement> Cases() => JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(
        File.ReadAllText(Environment.GetEnvironmentVariable("OFFICEIMO_COMPARISON_CASES")!))!;
    public static IEnumerable<string> Keys() => Cases().Keys;
    public static SnapshotProbe Load(string key, string version) {
        JsonElement spec = Cases()[key];
        if (Environment.GetEnvironmentVariable("OFFICEIMO_PERFORMANCE_AA") == "1") version = "baseline";
        string library = spec.GetProperty("Library").GetString()!;
        string root = Environment.GetEnvironmentVariable("OFFICEIMO_PERFORMANCE_SNAPSHOTS")!;
        string directory = Path.Combine(root, version + "-" + library.ToLowerInvariant());
        var context = new SnapshotContext(directory);
        string assemblyName = $"OfficeIMO.{library}.Benchmarks";
        var assembly = context.LoadFromAssemblyPath(Path.Combine(directory, assemblyName + ".dll"));
        Type type = assembly.GetType(assemblyName + "." + spec.GetProperty("Class").GetString(), true)!;
        object instance = Activator.CreateInstance(type)!;
        foreach (var setting in spec.GetProperty("Properties").EnumerateObject()) {
            var property = type.GetProperty(setting.Name)!;
            object value = property.PropertyType.IsEnum ? Enum.Parse(property.PropertyType, setting.Value.GetString()!)
                : JsonSerializer.Deserialize(setting.Value.GetRawText(), property.PropertyType)!;
            property.SetValue(instance, value);
        }
        object? setup = type.GetMethod(spec.GetProperty("Setup").GetString()!)!.Invoke(instance, null);
        if (setup is Task task) task.GetAwaiter().GetResult();
        var method = type.GetMethod(spec.GetProperty("Method").GetString()!)!;
        Func<Task<object?>> run;
        if (method.ReturnType.IsGenericType && method.ReturnType.GetGenericTypeDefinition() == typeof(Task<>)) {
            run = (Func<Task<object?>>)typeof(SnapshotProbe).GetMethod(nameof(BindAsync), BindingFlags.Static | BindingFlags.NonPublic)!
                .MakeGenericMethod(method.ReturnType.GenericTypeArguments[0]).Invoke(null, [instance, method])!;
        } else {
            var sync = Expression.Lambda<Func<object?>>(Expression.Convert(Expression.Call(Expression.Constant(instance), method), typeof(object))).Compile();
            run = () => Task.FromResult(sync());
        }
        var probe = new SnapshotProbe(instance, run);
        probe.OutputContract = type.GetProperty("ExpectedCsvSha256")?.GetValue(instance) as string;
        if (type.GetProperty("ExpectedOutputLengths")?.GetValue(instance) is IReadOnlyDictionary<string, long> lengths)
            probe.ExpectedResult = lengths[method.Name].ToString(System.Globalization.CultureInfo.InvariantCulture);
        return probe;
    }
    private static Func<Task<object?>> BindAsync<T>(object instance, MethodInfo method) {
        var action = (Func<Task<T>>)method.CreateDelegate(typeof(Func<Task<T>>), instance);
        return async () => await action().ConfigureAwait(false);
    }
    public void Dispose() {
        object? result = _instance.GetType().GetMethod("Cleanup")?.Invoke(_instance, null);
        if (result is Task task) task.GetAwaiter().GetResult();
    }
}
sealed class SnapshotContext(string directory) : AssemblyLoadContext {
    protected override Assembly? Load(AssemblyName name) {
        string path = Path.Combine(directory, name.Name + ".dll");
        return File.Exists(path) ? LoadFromAssemblyPath(path) : null;
    }
}

Scripts.MacRotation:
param([int] $Iterations = 24, [int] $Warmup = 32, [int] $Operations = 4,
    [string] $Cases = 'screen-cases.json', [string] $Label = 'screen-rotated', [switch] $IdenticalBaseline)
$ErrorActionPreference = 'Stop'
Import-Module PSPublishModule
$env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = Join-Path $PSScriptRoot 'net10.0'
$env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot $Cases
$env:OFFICEIMO_PERFORMANCE_AA = if ($IdenticalBaseline) { '1' } else { '0' }
$env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
if ([System.Runtime.InteropServices.RuntimeInformation]::FrameworkDescription -ne '.NET 10.0.12') { throw 'Expected actual NET10 validation host' }
# macOS uses operating-system scheduling; no unsupported controls.
[Reflection.Assembly]::LoadFrom((Join-Path $PSScriptRoot 'compare/bin/Release/net10.0/Compare.dll')) | Out-Null
$global:BufferProbes = @{}
$global:BufferExpected = @{}
$global:BufferOperations = $Operations
foreach ($key in [SnapshotProbe]::Keys()) {
    $before = [SnapshotProbe]::Load($key, 'baseline')
    $after = [SnapshotProbe]::Load($key, 'candidate')
    [SnapshotProbe]::ValidateEquivalent($before, $after)
    $global:BufferProbes[$key] = @{ Before = $before; After = $after }
    $global:BufferExpected[$key] = @{ Before=$before.ExpectedResult; After=$after.ExpectedResult }
}
try {
    Invoke-BenchmarkSuite -OutputRoot (Join-Path $PSScriptRoot "$Label") -WarmupCount $Warmup -IterationCount $Iterations -RunOrder Rotated -OutlierMode None -Settings {
        New-BenchmarkSuite 'CSV document text formatting qualification' {
            Add-BenchmarkMetadata Scheduling 'OS-Scheduled'
            Add-BenchmarkMetadata OperationsPerSample $Operations
            Add-BenchmarkMetadata IdenticalBaseline ([string]$IdenticalBaseline)
            Add-BenchmarkMetadata Runtime ([System.Runtime.InteropServices.RuntimeInformation]::FrameworkDescription)
            Add-BenchmarkMetadata Priority 'OS-Default'
            Add-BenchmarkCaseSource @($global:BufferProbes.Keys | Sort-Object | ForEach-Object { [pscustomobject]@{Name=$_} })
            Set-BenchmarkSetup {
                param($case, $run)
                $run.Probe = $global:BufferProbes[$case.Scenario][$case.Engine]
                $run.Expected = $global:BufferExpected[$case.Scenario][$case.Engine]
            }
            foreach ($engine in 'Before','After') {
                Add-BenchmarkEngine $engine {
                    Add-BenchmarkOperation WriteBatch {
                        param($case, $run)
                        for ($i=0; $i -lt $global:BufferOperations; $i++) { $run.Result = $run.Probe.RunSynchronously() }
                    }
                }
            }
            Add-BenchmarkValidation {
                param($case, $run)
                if ($run.Result.ToString() -ne $run.Expected) { throw 'Output length differs from this build''s independently validated CSV.' }
            }
            Add-BenchmarkComparison -Baseline Before -Metric MeanMs,MedianMs -TieTolerance 0.05
        }
    }
} finally {
    foreach ($pair in $global:BufferProbes.Values) { $pair.Before.Dispose(); $pair.After.Dispose() }
}

