Scripts.WindowsControls:
$ErrorActionPreference='Stop'
$full=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'full-cases.json') -Raw | ConvertFrom-Json -AsHashtable
$controls=[ordered]@{}
foreach($key in 'ToText-Plain-1','ToText-Quoted-1','ToText-MixedJson-1',
    'ToText-LongUnicode-3','ToText-LongUnicode-64','ToText-Quoted-100000','WriteDataReader-Plain-25000') {
    $controls[$key]=$full[$key]
}
$controls | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'control-cases.json') -Encoding utf8
$keys=@($controls.Keys | Sort-Object)
foreach($mode in 'AA','AB') {
    foreach($mask in 65535L,4294901760L) {
        for($offset=0;$offset -lt $keys.Count;$offset+=6) {
            $batch=[ordered]@{}
            foreach($key in $keys[$offset..([Math]::Min($offset+5,$keys.Count-1))]){$batch[$key]=$controls[$key]}
            $batchFile="control-batch-$offset.json"
            $batch | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $PSScriptRoot $batchFile) -Encoding utf8
            $label="control-$mode-batch-$offset"
            $arguments=@('-NoProfile','-File',(Join-Path $PSScriptRoot 'rotated.ps1'),'-Mask',$mask,
                '-Cases',$batchFile,'-Label',$label,'-Warmup',64,'-Iterations',48,'-Operations',8)
            if($mode -eq 'AA'){$arguments+='-IdenticalBaseline'}
            pwsh @arguments *> (Join-Path $PSScriptRoot "$label-$mask.log")
            if($LASTEXITCODE){throw "Control run failed: $mode / $mask / $offset"}
            Write-Output "Completed $mode followup batch $offset on $mask ($($batch.Count) workloads)."
        }
    }
}

Scripts.WindowsQualification:
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$cases = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'full-cases.json') -Raw | ConvertFrom-Json -AsHashtable
if ($cases.Count -ne 19) { throw 'Unexpected matrix' }
foreach ($framework in 'net10.0','net8.0') {
    $env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = Join-Path $PSScriptRoot $framework
    $env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot 'full-cases.json'
    $env:OFFICEIMO_COMPARISON_MASK = '65535'
    $env:OFFICEIMO_PERFORMANCE_AA = '0'
    $env:OFFICEIMO_BENCHMARK_PROCESS_PRIORITY = 'Normal'
    $env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
    $output = Join-Path $PSScriptRoot "full-native-$framework"
    if (Test-Path -LiteralPath $output) { throw "Output already exists: $output" }
    Push-Location (Join-Path $repo 'Ignore/Benchmarks/excel-csv-broad/compare')
    try {
        dotnet "bin/Release/$framework/Compare.dll" --filter '*SnapshotComparison*' --warmupCount 24 --iterationCount 12 --invocationCount 4 --unrollFactor 1 --outliers DontRemove --artifacts $output *> (Join-Path $PSScriptRoot "full-native-$framework.log")
        if ($LASTEXITCODE) { throw "Native run failed: $framework" }
    } finally { Pop-Location }
    $report = Get-Content -LiteralPath (Join-Path $output 'results/SnapshotComparison-report-full.json') -Raw | ConvertFrom-Json
    if ($report.Benchmarks.Count -ne 38 -or @($report.Benchmarks | Where-Object {$_.Statistics.N -ne 12}).Count) { throw "Incomplete native result: $framework" }
    Write-Output "Completed all 38 native text/adjacent cases on actual $framework."
}
$keys = @($cases.Keys | Sort-Object)
foreach ($mask in 65535L,4294901760L) {
    for ($offset=0; $offset -lt $keys.Count; $offset+=6) {
        $batch = [ordered]@{}
        foreach ($key in $keys[$offset..([Math]::Min($offset+5,$keys.Count-1))]) { $batch[$key]=$cases[$key] }
        $batchFile="full-batch-$offset.json"
        $batch | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $PSScriptRoot $batchFile) -Encoding utf8
        $label="full-batch-$offset"
        pwsh -NoProfile -File (Join-Path $PSScriptRoot 'rotated.ps1') -Mask $mask -Cases $batchFile -Label $label -Warmup 48 -Iterations 24 -Operations 4 *> (Join-Path $PSScriptRoot "$label-$mask.log")
        if ($LASTEXITCODE) { throw "Rotation failed: $mask / $offset" }
        Write-Output "Completed rotation batch $offset on $mask ($($batch.Count) workloads)."
    }
}
foreach ($framework in 'net10.0','net8.0') {
    $provenance=Get-Content -LiteralPath (Join-Path $PSScriptRoot "candidate-provenance-$framework.json") -Raw | ConvertFrom-Json
    foreach ($item in $provenance.Manifest) {
        foreach ($version in 'Before','After') {
            $folder=if($version -eq 'Before'){'baseline-csv'}else{'candidate-csv'}
            if ((Get-FileHash -LiteralPath (Join-Path $PSScriptRoot "$framework/$folder/$($item.File)")).Hash -ne $item.$version) { throw "Frozen input changed: $framework / $folder / $($item.File)" }
        }
    }
}
Write-Output 'Full text qualification completed; all frozen binary inputs still match.'

Scripts.MacQualification:
$ErrorActionPreference='Stop'
$full=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'compare/full-cases.json') -Raw | ConvertFrom-Json -AsHashtable
$controls=[ordered]@{}
foreach($key in 'ToText-Plain-1','ToText-Quoted-1','ToText-MixedJson-1','ToText-Plain-1000','ToText-Quoted-1000','ToText-MixedJson-1000','ToText-LongUnicode-3','ToText-LongUnicode-64','ToText-Quoted-100000','WriteDataReader-Plain-25000','SaveAsync-Plain-25000'){$controls[$key]=$full[$key]}
foreach($mode in 'FullAB','ControlAA','ControlAB') {
    $cases=if($mode -eq 'FullAB'){$full}else{$controls}
    $keys=@($cases.Keys | Sort-Object)
    for($offset=0;$offset -lt $keys.Count;$offset+=6) {
        $batch=[ordered]@{}
        foreach($key in $keys[$offset..([Math]::Min($offset+5,$keys.Count-1))]){$batch[$key]=$cases[$key]}
        $file="macos-$mode-batch-$offset.json"
        $batch | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $PSScriptRoot $file) -Encoding utf8
        $label="rotated-macos-$mode-batch-$offset"
        if(Test-Path -LiteralPath (Join-Path $PSScriptRoot $label)){throw 'Run output already exists'}
        $arguments=@('-NoProfile','-File',(Join-Path $PSScriptRoot 'rotated-macos.ps1'),'-Cases',$file,'-Label',$label)
        if($mode -eq 'FullAB'){$arguments+=@('-Warmup',48,'-Iterations',24,'-Operations',4)}else{$arguments+=@('-Warmup',64,'-Iterations',48,'-Operations',8)}
        if($mode -eq 'ControlAA'){$arguments+='-IdenticalBaseline'}
        & (Join-Path $PSScriptRoot 'powershell-7.6.6/pwsh') @arguments *> (Join-Path $PSScriptRoot "$label.log")
        if($LASTEXITCODE){throw "Mac rotation failed: $mode / $offset"}
        Write-Output "Completed Mac $mode / $offset ($($batch.Count) workloads)."
    }
}
$provenance=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'snapshot-provenance.json') -Raw | ConvertFrom-Json
foreach($runtime in 'net10.0','net8.0') {
    foreach($item in $provenance.Manifest.$runtime) {
        foreach($version in 'Before','After') {
            $folder=if($version -eq 'Before'){'baseline-csv'}else{'candidate-csv'}
            if((Get-FileHash -LiteralPath (Join-Path $PSScriptRoot "$runtime/$folder/$($item.File)")).Hash -ne $item.$version){throw "Frozen Mac input changed: $runtime / $folder / $($item.File)"}
        }
    }
}
Write-Output 'Mac rotated comparisons completed; frozen native binary manifests still match.'
